window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["chunking"]={"title":"文档切分 Chunking：决定检索系统的证据单位","subtitle":"理解固定长度、结构、语义与父子切分，处理重叠、上下文丢失、表格代码和嵌入预算。","thesis":"Chunking 将文档变成可检索和可引用的证据单元；块太小缺语境、太大稀释主题并增加成本。最佳切分由<b>文档结构、查询粒度、嵌入模型与生成任务</b>共同决定。","quality":{"contractVersion":2,"examples":[{"section":7,"evidence":{"setup":"一条退款政策应该怎样切","rule":"结构化父子切分用小单元提高命中率","steps":"L=120、w=40、o=10 得 n=4","interpretation":"只能由跨边界证据命中与最终答案改善决定"}}],"formulas":[{"id":"chunking-overlap-count","section":7,"formulaIndex":1,"symbols":[{"name":"n","meaning":"带重叠滑窗产生的近似块数","evidence":"输出块数 n"},{"name":"L","meaning":"原文 token 长度","evidence":"文档长度 L"},{"name":"w","meaning":"每个块的窗口 token 长度","evidence":"窗口 w"},{"name":"o","meaning":"相邻块重叠 token 数","evidence":"重叠 o"}]}],"termReviews":[],"sectionContracts":[{"section":1,"definition":{"answer":"文档切分把原文变成带定位信息的可检索证据单位。","evidence":"切分是检索的分辨率"},"problem":{"answer":"它解决答案跨边界、块缺语境或整篇过大稀释主题的问题。","evidence":"正确答案跨两个块时会发生什么"},"inputOutput":{"answer":"输入文档查询和预算，输出带原文位置的证据块。","evidence":"输出带原文位置的可检索证据块"},"mechanism":{"answer":"按真实答案跨度和结构决定边界并建立版本化索引。","evidence":"块定义了检索能直接找到的最小单位"},"interpretation":{"answer":"关键词命中不代表块包含完整判断条件。","evidence":"不表示块含有独立判断所需的完整条件"},"boundary":{"answer":"切分变化必须生成新 ID 和偏移，不能直接覆盖。","evidence":"不能直接覆盖导致引用失效"}},{"section":2,"definition":{"answer":"切分策略包括固定长度、结构、语义和父子切分。","evidence":"策略选择输入文档结构可靠性、主题边界和回填需求"},"problem":{"answer":"它回答固定五百 token 是否适用于所有文档。","evidence":"固定 500 token 是否适合所有文档"},"inputOutput":{"answer":"输入结构和回填需求，输出一种策略或组合。","evidence":"输出固定长度、结构、语义或父子切分及其组合"},"mechanism":{"answer":"分别按预算、标题、主题变化或父子层级划分。","evidence":"父子切分用小块定位并回填大块"},"interpretation":{"answer":"不同策略应按真实查询的证据完整性比较。","evidence":"按真实查询证据完整性比较"},"boundary":{"answer":"没有任何一种切分策略是所有文档的默认答案。","evidence":"不是所有文档的默认答案"}},{"section":3,"definition":{"answer":"重叠让相邻块重复一段边界内容以降低句子截断。","evidence":"重叠的收益与代价"},"problem":{"answer":"它处理答案恰好跨越两个窗口边界的问题。","evidence":"为什么相邻块常保留一段重复"},"inputOutput":{"answer":"输入窗口跨度和预算，输出重叠范围及合并规则。","evidence":"输出相邻块重复范围及检索后合并规则"},"mechanism":{"answer":"重复边界后在检索阶段按文档和邻接关系合并去重。","evidence":"增加索引、重复召回和上下文竞争"},"interpretation":{"answer":"收益看完整证据命中，代价看去重后 token。","evidence":"收益应看完整证据命中"},"boundary":{"answer":"重叠不能修复错误阅读顺序和权限串库。","evidence":"不能修复阅读顺序或权限错误"}},{"section":4,"definition":{"answer":"块元数据保存文档身份、层级、位置、版本和权限。","evidence":"保留元数据与层级"},"problem":{"answer":"它防止段落脱离标题后主语和适用范围丢失。","evidence":"一个段落离开标题后还表达同一意思吗"},"inputOutput":{"answer":"输入定位治理字段，输出可过滤可回查的证据单元。","evidence":"输出可定位、可过滤、可回查的证据单元"},"mechanism":{"answer":"标题辅助嵌入，引用始终指回原文坐标。","evidence":"引用仍必须指向原文坐标"},"interpretation":{"answer":"脱离标题语义改变的段落不能当作无上下文事实。","evidence":"不能作为无上下文事实"},"boundary":{"answer":"权限和版本必须跟随每个块传播。","evidence":"权限和版本必须随块一起传播"}},{"section":5,"definition":{"answer":"非纯文本切分先恢复材料特有的原子结构。","evidence":"非纯文本需要专门解析"},"problem":{"answer":"它防止字符硬切破坏表格、代码、PDF 和对话含义。","evidence":"表格、代码和 PDF 能按字符硬切吗"},"inputOutput":{"answer":"输入结构化材料，输出保留原子结构的证据块。","evidence":"输出保留各自原子结构的块"},"mechanism":{"answer":"先恢复阅读顺序表头依赖或指代，再执行切分。","evidence":"解析器先恢复阅读顺序、表头、函数依赖或指代实体，再切分"},"interpretation":{"answer":"检索失败可能其实是解析阶段已丢失正确内容。","evidence":"检索失败其实发生在索引之前"},"boundary":{"answer":"字符硬切只适合结构不重要且经过验证的文本。","evidence":"只适合结构不重要且已验证的连续文本"}},{"section":6,"definition":{"answer":"切分调参用证据和端到端任务指标联合选择块大小。","evidence":"怎样调块大小"},"problem":{"answer":"它判断应优化 Recall 还是最终答案正确率。","evidence":"应该优化 Recall@k 还是答案正确率"},"inputOutput":{"answer":"输入标注查询和候选任务，输出召回引用答案成本指标。","evidence":"输出证据召回、引用定位、答案、token、延迟和重复率"},"mechanism":{"answer":"先检查完整证据召回，再检查上下文和最终答案。","evidence":"先确保必要证据完整进入候选"},"interpretation":{"answer":"Recall 高而证据残缺仍表示切分方案失败。","evidence":"Recall 高但证据残缺仍不合格"},"boundary":{"answer":"不同查询粒度可用多套索引，不存在通用五百一十二。","evidence":"不存在通用最佳 512 token"}},{"section":7,"definition":{"answer":"退款案例比较固定、重叠和父子切分的证据完整性。","evidence":"一条退款政策应该怎样切"},"problem":{"answer":"它展示期限和质量例外被固定窗口拆开后的损失。","evidence":"检索器会看到什么"},"inputOutput":{"answer":"输入 L、w、o 和结构，输出 n、索引 token 与证据。","evidence":"输出块数 n、索引 token 与完整证据"},"mechanism":{"answer":"用步长 w 减 o 滑动，并向上取整得到块数。","evidence":"n 等于向上取整"},"interpretation":{"answer":"四块和百分之二十五膨胀是给定长度下的结果。","evidence":"L=120、w=40、o=10 得 n=4"},"boundary":{"answer":"是否值得必须由跨边界命中和答案改善决定。","evidence":"只能由跨边界证据命中与最终答案改善决定"}},{"section":8,"definition":{"answer":"边界材料需按 PDF、表格、代码和对话分别解析。","evidence":"边界案例如何分别处理"},"problem":{"answer":"它解释一个字符切分器为何同时破坏多类材料。","evidence":"为什么会同时破坏 PDF、表格、代码和对话"},"inputOutput":{"answer":"输入解析材料和约束，输出可还原含义的证据块。","evidence":"输出可独立还原含义的证据块和解析质量指标"},"mechanism":{"answer":"用渲染对照、表头覆盖、AST 和实体绑定验收。","evidence":"AST 检查和实体绑定"},"interpretation":{"answer":"检索不到可能是内容从未完整进入索引。","evidence":"正确内容从未进入索引"},"boundary":{"answer":"重叠不能补救双栏错序、串库或版本混合。","evidence":"不能补救双栏错序、串库或混版本"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>选择切分策略；设置长度与重叠；保留层级和来源；用检索与答案指标调参。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>切分是检索的分辨率<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">正确答案跨两个块时会发生什么？</p><p>召回器只能返回建立的单元。句子被截断、标题丢失或表格拆散，会让每个块都不完整；整篇过大又使嵌入平均掉局部主题。</p><p>建立切分基准时，应先从真实任务标注“最小充分证据跨度”：单句事实、同一小节内的条件与例外、跨表格行列、跨章节多跳分别占多少，再统计不同切法的完整证据命中率，而不只是包含答案关键词的块命中率。若 80% 查询只需单段、20% 需要父级语境，可让召回先命中小块，只对后者按邻接或标题路径扩展，不必让所有请求承担大块成本。</p><p>切分版本也必须可追踪。修改解析器或块大小后，块 id、原文偏移和嵌入应形成新版本；离线比较两套索引，确认引用仍能定位同一原文，再切换流量。直接覆盖会让回归样本、缓存和用户反馈指向已经不存在的块，形成难以复现的观测断裂。频繁更新的文档还要保证父块变化时子块一起失效，避免新标题配旧正文。</p><p>文档切分输入原始文档结构、典型查询、答案跨度和嵌入预算，输出带原文位置的可检索证据块。块定义了检索能直接找到的最小单位；命中关键词不表示块含有独立判断所需的完整条件。切分版本变化后必须保留新 ID、偏移和索引，不能直接覆盖导致引用失效。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>四类策略<span class=\"dd-badge eng\">方法</span></h2><p class=\"dd-lead\">固定 500 token 是否适合所有文档？</p><ul class=\"dd-steps\"><li>固定长度：简单可控，适合缺少可靠结构的连续文本，但边界与语义无关。</li><li>结构切分：按标题、段落、函数，引用稳定且可解释；坏解析器会继承坏结构。</li><li>语义切分：按相邻句表示变化寻找主题边界，能适应篇章，但阈值、模型和语言变化会导致版本漂移。</li><li>父子切分：小块召回、大块回填语境，在定位与完整之间折中；需防止多个子块重复带回同一父块。</li></ul><p>策略可以组合：先按章节建立不可跨越的硬边界，再在过长章节内按段落或语义切分，最后为短块继承标题路径。评价时保留切分器版本和原文偏移，才能解释某次命中是由内容变化还是边界变化造成。</p><p>策略选择输入文档结构可靠性、主题边界和回填需求，输出固定长度、结构、语义或父子切分及其组合。固定长度按预算切，结构切分尊重标题函数，语义切分检测主题变化，父子切分用小块定位并回填大块；结果应按真实查询证据完整性比较。任何策略都不是所有文档的默认答案。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>重叠的收益与代价<span class=\"dd-badge math\">权衡</span></h2><p class=\"dd-lead\">为什么相邻块常保留一段重复？</p><p>重叠降低边界截断概率，却扩大索引、产生重复召回并挤占上下文。去重和邻接合并应在检索后进行；重叠比例需按答案跨度实验，并分别报告去重前后的有效证据数。若多个命中块来自同一边界，应先合并再计算上下文预算。</p><p>重叠设计输入窗口长度、答案跨边界比例和上下文预算，输出相邻块重复范围及检索后合并规则。重复能让边界句在至少一个块内完整，却增加索引、重复召回和上下文竞争；收益应看完整证据命中，代价应看去重后的有效证据与 token。重叠不能修复阅读顺序或权限错误。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>保留元数据与层级<span class=\"dd-badge eng\">结构</span></h2><p class=\"dd-lead\">一个段落离开标题后还表达同一意思吗？</p><p>块应携带文档 id、标题路径、页码/行号、版本、时间和权限；必要时把短标题拼入嵌入文本，但引用仍指回原位置。</p><p>块元数据输入文档 ID、标题路径、页码行号、版本时间和权限，输出可定位、可过滤、可回查的证据单元。标题可拼入嵌入文本帮助理解，但引用仍必须指向原文坐标；脱离标题后语义改变的段落不能作为无上下文事实。权限和版本必须随块一起传播。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>非纯文本需要专门解析<span class=\"dd-badge intuition\">边界</span></h2><p class=\"dd-lead\">表格、代码和 PDF 能按字符硬切吗？</p><p>表格要保行列头，代码按函数/类并保依赖签名，PDF 先修复阅读顺序和页眉。解析错误常被误认为嵌入或模型失败。</p><p>专用解析输入 PDF 布局、表格行列、代码语法树或对话轮次，输出保留各自原子结构的块。解析器先恢复阅读顺序、表头、函数依赖或指代实体，再切分；否则检索失败其实发生在索引之前。字符硬切只适合结构不重要且已验证的连续文本。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>怎样调块大小<span class=\"dd-badge eng\">评测</span></h2><p class=\"dd-lead\">应该优化 Recall@k 还是答案正确率？</p><p>先测证据命中与引用，再测端到端答案、token、延迟和重复率。按事实查找、概念总结、多跳等查询类型分桶，可能需要多套索引。</p><div class=\"dd-note warn\"><b>没有通用最佳 512 token。</b>　它只是起始超参数。</div><p>切分调参输入标注查询、必要证据、候选索引和生成任务，输出证据召回、引用定位、答案、token、延迟和重复率。先确保必要证据完整进入候选，再检查上下文和最终任务；Recall 高但证据残缺仍不合格。不同查询粒度可能需要多套索引，不存在通用最佳 512 token。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>一条退款政策应该怎样切<span class=\"dd-badge math\">运行示例</span></h2><p class=\"dd-lead\">如果一般期限和质量例外恰好被固定窗口切开，检索器会看到什么？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 680 230\" role=\"img\" aria-label=\"同一退款政策采用固定切块与结构化父子切块的对比\"><defs><marker id=\"ch1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><text x=\"18\" y=\"25\" class=\"svg-t\">原文结构</text><rect x=\"18\" y=\"38\" width=\"644\" height=\"43\" rx=\"7\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"340\" y=\"56\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">H2 退货政策｜一般商品：签收 30 天内｜质量问题：经核验不受 30 天限制｜到账说明</text><text x=\"18\" y=\"111\" class=\"svg-t\">固定 20-token 边界</text><rect x=\"18\" y=\"124\" width=\"202\" height=\"50\" rx=\"7\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"119\" y=\"145\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">块 A：一般商品…30 天内。质量</text><text x=\"119\" y=\"162\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">（例外语义被截断）</text><rect x=\"232\" y=\"124\" width=\"202\" height=\"50\" rx=\"7\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"333\" y=\"145\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">块 B：问题经核验不受…到账</text><text x=\"333\" y=\"162\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">（主语和标题丢失）</text><text x=\"18\" y=\"206\" class=\"svg-t\">结构化父子切分</text><rect x=\"154\" y=\"187\" width=\"154\" height=\"37\" rx=\"7\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"231\" y=\"210\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">子块：30 天一般规则</text><rect x=\"320\" y=\"187\" width=\"176\" height=\"37\" rx=\"7\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"408\" y=\"210\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">子块：质量问题例外</text><path d=\"M496,205 L548,205\" stroke=\"#6b7484\" marker-end=\"url(#ch1)\"/><text x=\"605\" y=\"202\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">命中子块</text><text x=\"605\" y=\"217\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">回填完整 H2 父段</text></svg><figcaption>图 1　固定长度把句法和规则边界视为偶然位置；结构化父子切分用小单元提高命中率，再回填完整父段恢复条件与例外。</figcaption></figure><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>方案</th><th>块数</th><th>索引 token</th><th>查询“35 天质量问题”时的证据</th><th>主要代价</th></tr></thead><tbody><tr><td>40 token，无重叠</td><td>3</td><td>120</td><td>例外可能跨边界</td><td>低成本但脆弱</td></tr><tr><td>40 token，10 token 重叠</td><td>4</td><td>约 150</td><td>边界句更可能完整</td><td>索引约膨胀 25%，易重复召回</td></tr><tr><td>结构子块 + 80-token 父段</td><td>3 子块</td><td>约 120</td><td>子块命中后返回完整规则</td><td>需保存层级并控制回填预算</td></tr></tbody></table></div><p>对长度 <code>L=120</code>、窗口 <code>w=40</code>、重叠 <code>o=10</code>，步长是 <code>w-o=30</code>，块数约为 <code>ceil((L-w)/(w-o))+1=4</code>。总嵌入量约 160 token，但末块不足 40，实际约 150；与无重叠 120 相比增加约 25%。这笔成本是否值得，要看标注答案跨边界的比例，而不能凭经验固定。</p><div class=\"dd-note key\"><b>验收单位：</b>查询需要的是“30 天一般规则 + 质量问题例外 + 当前版本”。只命中包含“质量问题”的半句话不算成功；证据块必须让读者独立判断适用条件，并能回到原文位置。</div><p>退款案例输入文档长度 L、窗口 w、重叠 o 和规则结构，输出块数 n、索引 token 与完整证据。n 等于向上取整 (L−w)/(w−o) 后加一；L=120、w=40、o=10 得 n=4。百分之二十五索引膨胀是否值得，只能由跨边界证据命中与最终答案改善决定。</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"带重叠窗口的近似块数\"><mi>n</mi><mo>=</mo><mo>⌈</mo><mfrac><mrow><mi>L</mi><mo>−</mo><mi>w</mi></mrow><mrow><mi>w</mi><mo>−</mo><mi>o</mi></mrow></mfrac><mo>⌉</mo><mo>+</mo><mn>1</mn></math></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>边界案例如何分别处理<span class=\"dd-badge eng\">失败边界</span></h2><p class=\"dd-lead\">同一个字符切分器为什么会同时破坏 PDF、表格、代码和对话？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>材料</th><th>应保留的原子结构</th><th>常见静默失败</th><th>检验方法</th></tr></thead><tbody><tr><td>PDF</td><td>阅读顺序、标题路径、页码</td><td>双栏交错、页眉混入正文</td><td>抽样对照渲染页与解析文本</td></tr><tr><td>表格</td><td>列名、行标识、单位、脚注</td><td>数值离开表头后失去含义</td><td>要求每块能还原行列语义</td></tr><tr><td>代码</td><td>函数/类、签名、导入和必要调用方</td><td>语法完整但依赖上下文丢失</td><td>解析 AST，并运行引用/编译检查</td></tr><tr><td>对话</td><td>说话人、轮次、被指代实体</td><td>“它”“那个方案”失去指向</td><td>保留会话摘要或实体绑定</td></tr></tbody></table></div><p>解析质量应在嵌入之前单独设门禁：空块率、异常短块率、标题继承率、表格表头覆盖率和原文定位成功率。否则“检索不到”看起来像嵌入模型问题，实际正确句子从未以完整、可理解的形态进入索引。</p><div class=\"dd-note warn\"><b>失败边界：</b>重叠只能缓解偶然边界，不能修复错误阅读顺序、权限串库或版本混合。更大的 overlap 还会让同一证据以多个近重复块挤占 top-k，需要基于文档 id 与邻接关系去重。</div><p>边界材料处理输入解析后的 PDF、表格、代码或对话及其结构约束，输出可独立还原含义的证据块和解析质量指标。抽样对照渲染、表头覆盖、AST 检查和实体绑定用于确认结构未丢；检索不到可能是正确内容从未进入索引。重叠不能补救双栏错序、串库或混版本。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">9</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与路线</span></h2><p class=\"dd-lead\">切块不是把长文变短的预处理细节，而是在定义系统能够找到的最小证据。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>常见误解</th><th>更准确的理解</th></tr></thead><tbody><tr><td>统一 512 token 最稳</td><td>最佳粒度取决于文档结构、答案跨度、嵌入限制与查询类型</td></tr><tr><td>重叠越多越不丢信息</td><td>它提高边界覆盖，也增加索引、重复召回和上下文竞争</td></tr><tr><td>块越小检索越精准</td><td>小块可能命中关键词却缺少判断条件、主语和例外</td></tr><tr><td>父子切分就是返回整篇文档</td><td>小块负责定位，只扩展到能恢复必要语境的父级</td></tr><tr><td>Recall@k 高说明切分完成</td><td>还要检查证据完整、引用可定位、答案正确和 token 成本</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>token 与分词、上下文窗口、嵌入</td></tr><tr><td><b>本页核心</b></td><td>结构切分、语义边界、重叠、父子层级与元数据</td></tr><tr><td>紧邻</td><td>检索、向量数据库、重排、RAG</td></tr><tr><td>工程延伸</td><td>高级 RAG、知识图谱、Agent 记忆、数据治理和评测</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">10</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>解析文档恢复结构</li><li>按查询粒度选择单元</li><li>加入必要重叠和层级元数据</li><li>嵌入并建立索引</li><li>召回后邻接扩展与去重</li><li>用证据和答案指标共同调参</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">11</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>块太小的风险？</li><li>块太大的风险？</li><li>父子切分怎么工作？</li><li>重叠代价？</li><li>调参看哪些指标？</li><li>假设“文档切分 Chunking：决定检索系统的证据单位”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“文档切分 Chunking：决定检索系统的证据单位”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li><li>为什么不能只用一个平均分判断“文档切分 Chunking：决定检索系统的证据单位”已经可靠？应怎样按场景切片并设置失败边界？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>语境和跨句证据丢失。</li><li>主题稀释、成本和噪声增加。</li><li>小块检索，返回更大父块补语境。</li><li>索引膨胀和重复上下文。</li><li>证据召回、引用、答案、成本和延迟。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li><li>平均分会隐藏少数类别、极端输入、成本、延迟和安全失败。至少按难度、输入类型、长度或规模、风险等级及已知边界切片，同时报告质量、资源和失败率；高风险硬约束不能被其他切片的高分抵消。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2005.11401\" target=\"_blank\" rel=\"noopener\">Retrieval-Augmented Generation</a>：检索生成基础</li><li><a href=\"https://arxiv.org/abs/2409.04701\" target=\"_blank\" rel=\"noopener\">Late Chunking</a>：长上下文嵌入后切分</li><li><a href=\"https://arxiv.org/abs/2401.18059\" target=\"_blank\" rel=\"noopener\">RAPTOR</a>：层级递归摘要检索</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
